    // This observation owner recomputes g and E for every observation;\r\n            // it does not call the grouped-period path or share its pair cache.\r\n            glicko2_update_period(&expected,observations.data(),observations.size(),\r\n                                  LAPLACE_GLICKO2_DEFAULT_TAU,23);\r\n            ASSERT_EQ(expected.observation_count,17+static_cast<int64_t>(observations.size()));\r\n            ASSERT_EQ(0,glicko2_fold_grouped_period(\r\n                &actual,ratings.data(),rds.data(),games.data(),sums.data(),games.size(),\r\n                LAPLACE_GLICKO2_DEFAULT_TAU,23));\r\n            ExpectSameState(actual,expected);\r\n        }\r\n    }\r\n}"}, {"id": "21e1c72cbe934052f45b-17821", "name": "TEST", "repo": "Laplace", "path": "engine/core/tests/test_glicko2_extreme.cpp", "line": 431, "end_line": 450, "file": "21e1c72cbe934052f45b", "kind": "function_definition", "parse_error": false, "working_tree_changed": false, "calls": [{"name": "SCOPED_TRACE", "line": 433}, {"name": "glicko2_init", "line": 443}, {"name": "EXPECT_NE", "line": 446}, {"name": "glicko2_fold_grouped_period", "line": 446}, {"name": "ExpectSameState", "line": 448}], "structure": [{"kind": "for_statement", "line": 432, "end_line": 449, "label": "invalid<4", "children": [{"kind": "declaration", "line": 432, "end_line": 432, "label": "int invalid=0;", "children": []}, {"kind": "expression_statement", "line": 433, "end_line": 433, "label": "SCOPED_TRACE(invalid);", "children": []}, {"kind": "declaration", "line": 434, "end_line": 434, "label": "int64_t ratings[]={1756000000000LL,1756000000000LL};", "children": []}, {"kind": "declaration", "line": 435, "end_line": 435, "label": "int64_t rds[]={62000000000LL,62000000000LL};", "children": []}, {"kind": "declaration", "line": 436, "end_line": 436, "label": "int64_t games[]={3,3};", "children": []}, {"kind": "declaration", "line": 437, "end_line": 437, "label": "int64_t sums[]={1000000000LL,1000000001LL};", "children": []},